    }
    // order 3
    var ord3 = 1
    var moved = 0
    i = 0
    while i < 16 {
        if pi[pi[pi[i as usize] as usize] as usize] != i { ord3 = 0 }
        if pi[i as usize] != i { moved = 1 }
