fn g0<T>(x: T) -> W<T> { W { v: x } }
fn g1<T>(x: T) -> W<T> { W { v: x } }
fn g2<T>(x: T) -> W<T> { W { v: x } }
fn g3<T>(x: T) -> W<T> { W { v: x } }
fn g4<T>(x: T) -> W<T> { W { v: x } }
