// ============================================================================
// 1D ELEMENT ROUTINES (copied from fem.sio)
// ============================================================================

fn fem_1d_stiffness(x1: f64, x2: f64, EA: f64, ke: &![f64; 4]) with Mut, Div, Panic {
    let L = fe_abs(x2 - x1)
    let k = EA / L
    ke[0] = k
    ke[1] = 0.0 - k
    ke[2] = 0.0 - k
    ke[3] = k
}

fn fem_1d_mass(x1: f64, x2: f64, rho_A: f64, me: &![f64; 4]) with Mut, Div, Panic {
    let L = fe_abs(x2 - x1)
    let c = rho_A * L / 6.0
    me[0] = 2.0 * c
    me[1] = c
    me[2] = c
    me[3] = 2.0 * c
}

fn fem_1d_load(x1: f64, x2: f64, q: f64, fe: &![f64; 2]) with Mut, Div, Panic {
    let L = fe_abs(x2 - x1)
    let c = q * L / 2.0
    fe[0] = c
    fe[1] = c
}

// ============================================================================
// 2D CST ELEMENT ROUTINES (copied from fem.sio)
// ============================================================================

fn fem_tri_area(x1: f64, y1: f64, x2: f64, y2: f64, x3: f64, y3: f64) -> f64 with Mut, Div {
    let det = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)
    0.5 * fe_abs(det)
}

fn fem_tri_shape(x1: f64, y1: f64, x2: f64, y2: f64, x3: f64, y3: f64,
                 x: f64, y: f64, N: &![f64; 3]) with Mut, Div, Panic {
    let A2 = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)
    N[0] = (x * (y2 - y3) + x2 * (y3 - y) + x3 * (y - y2)) / A2
    N[1] = (x1 * (y - y3) + x * (y3 - y1) + x3 * (y1 - y)) / A2
    N[2] = (x1 * (y2 - y) + x2 * (y - y1) + x * (y1 - y2)) / A2
}

fn fem_tri_grad(x1: f64, y1: f64, x2: f64, y2: f64, x3: f64, y3: f64,
                B: &![f64; 18]) with Mut, Div, Panic {
    let A2 = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)
    let inv2A = 1.0 / A2

    let b1 = y2 - y3
    let b2 = y3 - y1
    let b3 = y1 - y2
    let c1 = x3 - x2
    let c2 = x1 - x3
    let c3 = x2 - x1

    B[0] = b1 * inv2A
    B[1] = 0.0
    B[2] = b2 * inv2A
    B[3] = 0.0
    B[4] = b3 * inv2A
    B[5] = 0.0

    B[6] = 0.0
    B[7] = c1 * inv2A
    B[8] = 0.0
    B[9] = c2 * inv2A
    B[10] = 0.0
    B[11] = c3 * inv2A

    B[12] = c1 * inv2A
    B[13] = b1 * inv2A
    B[14] = c2 * inv2A
    B[15] = b2 * inv2A
    B[16] = c3 * inv2A
    B[17] = b3 * inv2A
}

fn fem_tri_stiffness(x1: f64, y1: f64, x2: f64, y2: f64, x3: f64, y3: f64,
                     D: &[f64; 9], thickness: f64, ke: &![f64; 36]) with Mut, Div, Panic {
    let A = fem_tri_area(x1, y1, x2, y2, x3, y3)

    var B: [f64; 18] = [0.0; 18]
    fem_tri_grad(x1, y1, x2, y2, x3, y3, &!B)

    var DB: [f64; 18] = [0.0; 18]
    var i = 0
    while i < 3 {
        var j = 0
        while j < 6 {
            var s = 0.0
            var k = 0
            while k < 3 {
                s = s + D[i * 3 + k] * B[k * 6 + j]
                k = k + 1
            }
            DB[i * 6 + j] = s
            j = j + 1
        }
        i = i + 1
    }

    let scale = thickness * A
    i = 0
    while i < 6 {
        var j = 0
        while j < 6 {
            var s = 0.0
            var k = 0
            while k < 3 {
                s = s + B[k * 6 + i] * DB[k * 6 + j]
                k = k + 1
            }
            ke[i * 6 + j] = scale * s
            j = j + 1
        }
        i = i + 1
    }
}

// ============================================================================
// CONSTITUTIVE MATRICES (copied from fem.sio)
// ============================================================================

fn fem_plane_stress(E: f64, nu: f64, D: &![f64; 9]) with Mut, Div, Panic {
    let c = E / (1.0 - nu * nu)
    D[0] = c
    D[1] = c * nu
    D[2] = 0.0
    D[3] = c * nu
    D[4] = c
    D[5] = 0.0
    D[6] = 0.0
    D[7] = 0.0
    D[8] = c * (1.0 - nu) / 2.0
}

// ============================================================================
// 1D ASSEMBLY (copied from fem.sio)
// ============================================================================

fn fem_assemble_stiffness_1d(mesh: &FEMesh1D, EA: f64, K: &![f64; 4096]) with Mut, Div, Panic {
    let n = mesh.n_nodes
    var idx = 0
    while idx < n * n { K[idx] = 0.0; idx = idx + 1 }

    var e = 0
    while e < mesh.n_elem {
        let n1 = mesh.elements[2 * e]
        let n2 = mesh.elements[2 * e + 1]
        let x1 = mesh.nodes[n1]
        let x2 = mesh.nodes[n2]

        var ke: [f64; 4] = [0.0; 4]
        fem_1d_stiffness(x1, x2, EA, &!ke)

        K[n1 * n + n1] = K[n1 * n + n1] + ke[0]
        K[n1 * n + n2] = K[n1 * n + n2] + ke[1]
        K[n2 * n + n1] = K[n2 * n + n1] + ke[2]
        K[n2 * n + n2] = K[n2 * n + n2] + ke[3]

        e = e + 1
    }
}

fn fem_assemble_load_1d(mesh: &FEMesh1D, q: f64, F: &![f64; 256]) with Mut, Div, Panic {
    let n = mesh.n_nodes
    var idx = 0
    while idx < n { F[idx] = 0.0; idx = idx + 1 }

    var e = 0
    while e < mesh.n_elem {
        let n1 = mesh.elements[2 * e]
        let n2 = mesh.elements[2 * e + 1]
        let x1 = mesh.nodes[n1]
        let x2 = mesh.nodes[n2]

        var fe: [f64; 2] = [0.0; 2]
        fem_1d_load(x1, x2, q, &!fe)

        F[n1] = F[n1] + fe[0]
        F[n2] = F[n2] + fe[1]

        e = e + 1
    }
}

// ============================================================================
// 2D ASSEMBLY (copied from fem.sio)
// ============================================================================

fn fem_assemble_stiffness_2d(mesh: &FEMesh2D, D: &[f64; 9], thickness: f64,
                             K: &![f64; 4096]) with Mut, Div, Panic {
    let n_dof = 2 * mesh.n_nodes
    var idx = 0
    while idx < n_dof * n_dof { K[idx] = 0.0; idx = idx + 1 }

    var e = 0
    while e < mesh.n_elem {
        let n1 = mesh.elements[3 * e]
        let n2 = mesh.elements[3 * e + 1]
        let n3 = mesh.elements[3 * e + 2]

        let x1 = mesh.nodes_x[n1]
        let y1 = mesh.nodes_y[n1]
        let x2 = mesh.nodes_x[n2]
        let y2 = mesh.nodes_y[n2]
        let x3 = mesh.nodes_x[n3]
        let y3 = mesh.nodes_y[n3]

        var ke: [f64; 36] = [0.0; 36]
        fem_tri_stiffness(x1, y1, x2, y2, x3, y3, D, thickness, &!ke)

        var dof_map: [i32; 6] = [0; 6]
        dof_map[0] = 2 * n1
        dof_map[1] = 2 * n1 + 1
        dof_map[2] = 2 * n2
        dof_map[3] = 2 * n2 + 1
        dof_map[4] = 2 * n3
        dof_map[5] = 2 * n3 + 1

        var i = 0
        while i < 6 {
            var j = 0
            while j < 6 {
                let gi = dof_map[i]
                let gj = dof_map[j]
                K[gi * n_dof + gj] = K[gi * n_dof + gj] + ke[i * 6 + j]
                j = j + 1
            }
            i = i + 1
        }

        e = e + 1
    }
}

